from __future__ import annotations
from typing import Dict, List, Tuple

State = Dict[str, int]

def get(x: State, s: str) -> int:
    return x.get(s, 0)

def enabled(reactant: State, x: State) -> bool:
    return all(get(x, s) >= n for s, n in reactant.items())

def fire(reactant: State, product: State, x: State, species: List[str]) -> State:
    return {s: max(get(x, s) - get(reactant, s), 0) + get(product, s) for s in species}

def mass(w: Dict[str, int], x: State, species: List[str]) -> int:
    return sum(w.get(s, 0) * get(x, s) for s in species)

def run() -> None:
    species = ["A", "B", "C"]
    reactant, product = {"A": 1, "B": 1}, {"C": 1}   # A + B -> C
    x: State = {"A": 3, "B": 2, "C": 0}
    print("enabled:", enabled(reactant, x))
    y = fire(reactant, product, x, species)
    print("fire(x):", y)
    d = {"A": 5, "C": 7}
    lhs = fire(reactant, product, {s: get(x, s) + get(d, s) for s in species}, species)
    rhs = {s: get(y, s) + get(d, s) for s in species}
    print("strong monotonicity fire(x+d)=fire(x)+d:", lhs == rhs)
    w = {"A": 1, "B": 1, "C": 2}   # balanced: 1+1 == 2
    print("conserved mass:", mass(w, x, species), "->", mass(w, y, species))

if __name__ == "__main__":
    run()

from __future__ import annotations
from math import ceil, floor, log2

def parallel_time_lower_bound(work: int, parallelism: int) -> int:
    return ceil(work / parallelism)

def speedup_cap(work: int, parallelism: int) -> int:
    return min(parallelism, work)

def run() -> None:
    P = 10 ** 24  # fixed molecule budget (~2^80)
    print(f"P = {P:.0e}  (~2^{floor(log2(P))})")
    for n in [60, 80, 100, 120]:
        work = 2 ** n
        print(f"n={n:>4}  work=2^n={work:.2e}  parallel time >= 2^n/P = {work // P:.2e}")
    print("Exponential work -> unbounded parallel time under any fixed volume.")
    for W, p in [(1000, 8), (10**6, 1000), (10**9, 10**6)]:
        print(f"W={W}, p={p}: min steps={parallel_time_lower_bound(W,p)}, speedup<={speedup_cap(W,p)}")

if __name__ == "__main__":
    run()

from __future__ import annotations
from math import ceil, log2

def min_units_for(num_states: int) -> int:
    return ceil(log2(num_states)) if num_states > 1 else 0

def capacity(k: int) -> int:
    return 2 ** k

def run() -> None:
    for N in [2, 256, 10**6, 10**18]:
        k = min_units_for(N)
        print(f"N={N:>20}: need k>={k:>3} units (2^k={capacity(k):.3e})")
    assert 2**59 < 10**18 <= 2**60
    print("Density check: 2^59 < 10^18 <= 2^60, so ceil(log2(10^18)) = 60.")

if __name__ == "__main__":
    run()

