function COVERABLE(reactions, start, target):
    seen <- {start};  Q <- queue(start)
    while Q not empty:
        x <- dequeue(Q)
        if x >= target componentwise: return TRUE
        for (reactant, product) in reactions:
            if reactant <= x componentwise:
                y <- x - reactant + product
                if y not in seen: add y to seen and Q
    return FALSE

