function ANALYZE_SPEEDUP(W, p, P):
    p_eff <- min(p, P)
    T_min <- ceil(W / p_eff)          # parallel time lower bound
    speedup <- min(p_eff, W)          # speedup cap (constant factor)
    return {T_min, speedup, sequential = W, p_eff}
